{
SELECT ?name (COUNT(*) AS ?total) (SUM(?woman) AS ?women) (SUM(?woman)/COUNT(*) AS ?ratio) WHERE { # should be (?women/?total AS ?ratio) - see T172113
?person wdt:[property:instance of] wd:[entity:human];
wdt:[property:given name] ?name;
wdt:[property:sex or gender] ?sexOrGender;
wdt:[property:date of birth] ?dob.
BIND(IF(?sexOrGender IN (wd:[entity:female], wd:[entity:trans woman]), 1, 0) AS ?woman)
}
GROUP BY ?name
HAVING(?total >= 10 && 0.4 <= ?ratio && ?ratio <= 0.6) # arbitrary limits, feel free to tweak
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?total)

